PREFIX lila: <http://lila-erc.eu/ontologies/lila/>
PREFIX ontolex: <http://www.w3.org/ns/lemon/ontolex#>

SELECT DISTINCT (?c_variantWR AS ?variantWR)
WHERE {
  GRAPH <http://liita.it/data> {
    VALUES ?a_lemmaType { lila:Lemma lila:Hypolemma }
    ?a_lemma a ?a_lemmaType .
    ?a_lemma lila:hasPOS lila:verb .
    ?a_lemma ontolex:writtenRep ?a_wr .
    FILTER(STR(?a_wr) = "distribuire") .
  }
  GRAPH <http://liita.it/data> {
    { ?a_lemma lila:lemmaVariant ?c_variantLemma } UNION { ?c_variantLemma lila:lemmaVariant ?a_lemma }
    ?c_variantLemma ontolex:writtenRep ?c_variantWR .
  }
}

PREFIX lila: <http://lila-erc.eu/ontologies/lila/>
PREFIX ontolex: <http://www.w3.org/ns/lemon/ontolex#>

SELECT DISTINCT (?c_hypolemmaWR AS ?hypolemmaWR)
WHERE {
  GRAPH <http://liita.it/data> {
    VALUES ?a_lemmaType { lila:Lemma lila:Hypolemma }
    ?a_lemma a ?a_lemmaType .
    ?a_lemma ontolex:writtenRep ?a_wr .
    FILTER(STR(?a_wr) = "manifestare") .
  }
  GRAPH <http://liita.it/data> { ?c_hypolemma lila:isHypolemma ?a_lemma ; ontolex:writtenRep ?c_hypolemmaWR . }
}

