PREFIX lila: <http://lila-erc.eu/ontologies/lila/>
PREFIX marl: <http://www.gsi.upm.es/ontologies/marl/ns#>
PREFIX ontolex: <http://www.w3.org/ns/lemon/ontolex#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?highestPolarity ?lowestPolarity
WHERE {
  { SELECT (MAX(xsd:float(?s1_polarityValue)) AS ?highestPolarity) WHERE {
      GRAPH <http://liita.it/data> {
        VALUES ?w1_lemmaType { lila:Lemma lila:Hypolemma }
        ?w1_lemma a ?w1_lemmaType .
        ?w1_lemma ontolex:writtenRep ?w1_wr .
        FILTER(STR(?w1_wr) = "coltura") .
      }
      ?s1_sentixLemma ontolex:canonicalForm ?w1_lemma ;
                   marl:hasPolarity ?s1_polarity ;
                   marl:hasPolarityValue ?s1_polarityValue .
      BIND(STRAFTER(STR(?s1_polarity), "#") AS ?s1_polarityLabel)
    }
  }
  { SELECT (MIN(xsd:float(?s2_polarityValue)) AS ?lowestPolarity) WHERE {
      GRAPH <http://liita.it/data> {
        VALUES ?w2_lemmaType { lila:Lemma lila:Hypolemma }
        ?w2_lemma a ?w2_lemmaType .
        ?w2_lemma ontolex:writtenRep ?w2_wr .
        FILTER(STR(?w2_wr) = "coltura") .
      }
      ?s2_sentixLemma ontolex:canonicalForm ?w2_lemma ;
                   marl:hasPolarity ?s2_polarity ;
                   marl:hasPolarityValue ?s2_polarityValue .
      BIND(STRAFTER(STR(?s2_polarity), "#") AS ?s2_polarityLabel)
    }
  }
}

