      ?u_seedWord a ontolex:Word ;
                lexinfo:partOfSpeech [ rdfs:label ?h_posLabel ] ;
                ontolex:canonicalForm [ ontolex:writtenRep ?h_seedForm ] ;
                ontolex:sense ?h_seedSense .
      FILTER(str(?h_seedForm) = "capinera") .
      ?u_senseRel lexinfo:hyponym ?h_seedSense .
      OPTIONAL { ?u_senseRel skos:definition ?u_definition . }
      ?u_wordRel ontolex:sense ?u_senseRel ;
               ontolex:canonicalForm ?h_formRel .
      ?h_formRel ontolex:writtenRep ?u_itLemmaString .
