                lexinfo:partOfSpeech [ rdfs:label ?m_posLabel ] ;
                ontolex:canonicalForm [ ontolex:writtenRep ?m_seedForm ] ;
                ontolex:sense ?m_seedSense .
      FILTER(str(?m_seedForm) = "capinera") .
      ?u_senseRel lexinfo:partMeronym ?m_seedSense .
      OPTIONAL { ?u_senseRel skos:definition ?u_definition . }
      ?u_wordRel ontolex:sense ?u_senseRel ;
               ontolex:canonicalForm ?m_formRel .
      ?m_formRel ontolex:writtenRep ?u_itLemmaString .
