      ?ws_sentixLemma ontolex:canonicalForm ?w_lemma ;
                   marl:hasPolarity ?ws_polarity ;
                   marl:hasPolarityValue ?ws_polarityValue .
      BIND(STRAFTER(STR(?ws_polarity), "#") AS ?ws_polarityLabel)
    }
  }
